<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Notification\Outbox\Application\Usecase\Enqueue;

use LogicException;
use Ramsey\Uuid\Uuid;
use Throwable;
use Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render\TemplateRenderInput;
use Civi\Lughauth\Features\Document\Rendering\Application\Usecase\Render\TemplateRenderUsecase;
use Civi\Lughauth\Features\Document\Rendering\Domain\TemplateOutputFormat;
use Civi\Lughauth\Features\Notification\Message\Domain\Message;
use Civi\Lughauth\Features\Notification\Message\Domain\MessageAttributes;
use Civi\Lughauth\Features\Notification\Message\Domain\Gateway\MessageWriteGateway;
use Civi\Lughauth\Features\Notification\Outbox\Application\Service\NotificationDispatchService;
use Civi\Lughauth\Features\Notification\Outbox\Domain\Event\UrgentMessageEnqueuedEvent;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;
use Psr\EventDispatcher\EventDispatcherInterface;

/**
 * Creates a Message in the outbox by rendering the requested template and persisting the
 * result as a pending notification.
 *
 * The rendered content (subject + HTML + optional plain text) is serialised to JSON and stored in
 * Message::getContent() so the dispatch service can reconstruct the email without re-rendering.
 *
 * For urgent messages, a register_shutdown_function is registered to trigger an immediate dispatch
 * cycle at end of request (after the response has been sent to the client). This ensures the
 * outbox is flushed without depending exclusively on the scheduler.
 */
class EnqueueNotificationUsecase
{
    use LoggerAwareTrait;
    use TracerAwareTrait;

    public function __construct(
        private readonly TemplateRenderUsecase $renderUsecase,
        private readonly MessageWriteGateway $messageWriter,
        private readonly NotificationDispatchService $dispatchService,
        private readonly EventDispatcherInterface $dispatcher,
    ) {
    }

    /**
     * Renders the template and persists the resulting message in the outbox queue.
     *
     * @throws LogicException when no enabled template is found for the given code and channel.
     */
    public function enqueue(EnqueueNotificationCommand $cmd): Message
    {
        $this->logDebug("Enqueuing notification for template={code}", ['code' => $cmd->templateCode()]);
        $span = $this->startSpan("outbox.enqueue");
        try {
            $renderInput = new TemplateRenderInput(
                code:         $cmd->templateCode(),
                channel:      $cmd->channel(),
                tenant:       $cmd->tenant(),
                variables:    $this->flattenVariables('', $cmd->variables()),
                outputFormat: TemplateOutputFormat::HTML_EMBEDDED,
            );

            $renderResult = $this->renderUsecase->render($renderInput);

            if (!$renderResult->found()) {
                throw new LogicException(
                    "No enabled template found for code={$cmd->templateCode()} channel={$cmd->channel()->value}"
                );
            }

            $rendered = $renderResult->rendered();
            $content  = $this->encodeContent(
                subject:     $rendered->getSubject() ?? '',
                html:        $rendered->htmlContent(),
                text:        $rendered->getTextContent(),
            );

            $attrs = (new MessageAttributes())
                ->uid(Uuid::uuid4()->toString())
                ->target($cmd->recipient())
                ->content($content)
                ->retries(0)
                ->urgent($cmd->isUrgent());

            if (null !== $cmd->tenant()) {
                $attrs->tenant($cmd->tenant());
            }

            $message = Message::create($attrs);
            $saved   = $this->messageWriter->create($message);

            $this->logDebug("Enqueued message uid={uid} urgent={urgent}", [
                'uid'    => $saved->uid(),
                'urgent' => $cmd->isUrgent() ? 'true' : 'false',
            ]);

            if ($cmd->isUrgent()) {
                $this->scheduleUrgentDispatch($saved->uid());
            }

            return $saved;
        } catch (Throwable $ex) {
            $span->recordException($ex);
            throw $ex;
        } finally {
            $span->end();
        }
    }

    // ---------------------------------------------------------------------------
    // Urgent dispatch via register_shutdown_function
    // ---------------------------------------------------------------------------

    /**
     * Registers a shutdown function to dispatch pending messages at end of request.
     *
     * The shutdown function fires after the response is sent to the client (in PHP-FPM
     * environments that call fastcgi_finish_request()). This guarantees:
     *   1. The current transaction is already committed and the message is visible in DB.
     *   2. The dispatch does not add latency to the HTTP response.
     *
     * Dispatch failures are swallowed here; the scheduler will retry on the next cycle.
     */
    private function scheduleUrgentDispatch(string $messageUid): void
    {
        $this->dispatcher->dispatch(new UrgentMessageEnqueuedEvent($messageUid));

        $dispatchService = $this->dispatchService;
        $logger          = fn (string $msg) => $this->logWarning($msg);

        register_shutdown_function(static function () use ($dispatchService, $messageUid, $logger): void {
            try {
                $dispatchService->dispatch();
            } catch (Throwable $ex) {
                $logger("Immediate dispatch for urgent message uid={$messageUid} failed: {$ex->getMessage()}");
            }
        });
    }

    // ---------------------------------------------------------------------------
    // Content encoding
    // ---------------------------------------------------------------------------

    /**
     * Serialises the rendered template output to a JSON string for storage in the outbox.
     *
     * Format: {"subject":"…","html":"…","text":"…"}
     * Falls back to raw HTML when JSON encoding fails so the message is never silently lost.
     */
    private function encodeContent(string $subject, string $html, ?string $text): string
    {
        $encoded = json_encode(['subject' => $subject, 'html' => $html, 'text' => $text]);

        if (false === $encoded) {
            $this->logWarning("Failed to JSON-encode rendered template content, using html only");
            return $html;
        }

        return $encoded;
    }

    // ---------------------------------------------------------------------------
    // Variable flattening
    // ---------------------------------------------------------------------------

    /**
     * Recursively flattens a nested variable map to dotted-key notation.
     *
     * Example: ["user" => ["name" => "Alice"]] → ["user.name" => "Alice"]
     * Null values are skipped; non-array values are converted with (string).
     *
     * @param  array<string, mixed> $map
     * @return array<string, string>
     */
    private function flattenVariables(string $prefix, array $map): array
    {
        $result = [];

        foreach ($map as $key => $value) {
            $fullKey = $prefix === '' ? $key : $prefix . '.' . $key;

            if (is_array($value)) {
                $result = array_merge($result, $this->flattenVariables($fullKey, $value));
            } elseif (null !== $value) {
                $result[$fullKey] = (string) $value;
            }
        }

        return $result;
    }
}
